#!/bin/bash
set -euo pipefail
export LD_LIBRARY_PATH=/tmp/glob2-sdl3/prefix/lib
python3 docs/.work/run_with_shared_host_cpuset.py --audit artifacts/resource-growth/remaining/cpuset-stages.json --cpus 0-3 --reserve-cpus 0-3,16-19 --timeout-seconds 1800 -- python3 test/run_with_benchmark_governor.py --audit artifacts/resource-growth/remaining/governor-stages.json --cpus 0 1 2 3 -- python3 docs/.work/run-growth-remaining-stages.py > artifacts/resource-growth/remaining/stages.log 2>&1
python3 docs/.work/run_with_shared_host_cpuset.py --audit artifacts/resource-growth/remaining/cpuset-confirmation.json --cpus 0-3 --reserve-cpus 0-3,16-19 --timeout-seconds 7200 -- python3 test/run_with_benchmark_governor.py --audit artifacts/resource-growth/remaining/governor-confirmation.json --cpus 0 1 2 3 -- python3 docs/.work/run-growth-final-pairs.py artifacts/resource-growth/remaining/confirmation-plan.json > artifacts/resource-growth/remaining/confirmation.log 2>&1
python3 docs/.work/run_with_shared_host_cpuset.py --audit artifacts/resource-growth/remaining/cpuset-sensitivity.json --cpus 0-3,8-11 --reserve-cpus 0-3,8-11,16-19,24-27 --timeout-seconds 7200 -- python3 test/run_with_benchmark_governor.py --audit artifacts/resource-growth/remaining/governor-sensitivity.json --cpus 0 1 2 3 8 9 10 11 -- python3 docs/.work/run-growth-final-pairs.py artifacts/resource-growth/remaining/sensitivity-plan.json > artifacts/resource-growth/remaining/sensitivity.log 2>&1
